// Append-only, deterministic practice bank. Numerical variations reinforce shared skills.
const POP_SOURCES={taylor:{label:'Recording Academy · Taylor Swift',url:'https://www.grammy.com/artists/taylor-swift/15450/',checked:'10 November 2026'},billie:{label:'Recording Academy · 2024 Song of the Year',url:'https://www.grammy.com/news/2024-grammys-billie-eilish-wins-song-of-the-year-what-was-i-made-for-barbie/',checked:'10 November 2026'},frozen:{label:'Disney · Frozen music',url:'https://video.disney.com/watch/disney-s-frozen-let-it-go-sequence-performed-by-idina-menzel-4ecd3e729706a16e5090f1de',checked:'10 November 2026'},encanto:{label:'Disney · Encanto songs',url:'https://www.disneylatino.com/novedades/quien-canta-las-canciones-de-encanto-en-espanol',checked:'10 November 2026'}};
const POP_QUESTIONS=[
['taylor','Which artist released the album 1989?',['Taylor Swift','Billie Eilish','Adele','Olivia Rodrigo'],'1989 is an album by Taylor Swift. An album is a collection of recorded tracks.'],
['taylor','Which Taylor Swift album won Album of the Year at the 2010 Grammy Awards?',['Fearless','1989','Midnights','Folklore'],'Fearless received Album of the Year at the 2010 awards. Awards have dates, so the year is part of the question.'],
['taylor','Which Taylor Swift album won Album of the Year at the 2021 Grammy Awards?',['Folklore','Fearless','1989','Midnights'],'Folklore won the award in 2021. It is a different album from the other options.'],
['taylor','Which Taylor Swift album won Album of the Year at the 2024 Grammy Awards?',['Midnights','Fearless','1989','Folklore'],'Midnights received the 2024 award. This is a dated music-history fact.'],
['billie','Which film featured Billie Eilish’s song What Was I Made For?',['Barbie','Frozen','Encanto','Moana'],'The song was written for Barbie. Film songs can help communicate a character’s feelings.'],
['billie','Who co-wrote What Was I Made For? with Billie Eilish?',['FINNEAS','John Williams','Hans Zimmer','Lin-Manuel Miranda'],'FINNEAS and Billie Eilish wrote the song together. Songwriting is often collaborative.'],
['billie','How are Billie Eilish and FINNEAS related?',['They are siblings','They are cousins','They are parent and child','They are unrelated'],'FINNEAS is Billie Eilish’s brother and a collaborator in her music.'],
['billie','What Was I Made For? won which award at the 2024 Grammys?',['Song of the Year','Best Comedy Album','Best Historical Album','Best Opera Recording'],'The song received Song of the Year, a songwriting award.'],
['frozen','Which Disney film includes the song Let It Go?',['Frozen','Encanto','The Lion King','Coco'],'Let It Go appears in Frozen. The question asks about the film rather than the song’s words.'],
['frozen','Which Frozen character performs Let It Go?',['Elsa','Anna','Olaf','Kristoff'],'Elsa performs the song in Frozen. Songs can reveal a character’s changing emotions.'],
['frozen','Who voices Elsa’s singing in the original English-language Frozen film?',['Idina Menzel','Ariana Grande','Billie Eilish','Taylor Swift'],'Idina Menzel performs Elsa’s singing in the original English-language film.'],
['frozen','Which songwriting team wrote Let It Go?',['Kristen Anderson-Lopez and Robert Lopez','Billie Eilish and FINNEAS','Paul McCartney and John Lennon','Elton John and Tim Rice'],'Kristen Anderson-Lopez and Robert Lopez wrote the song. The singers and the songwriters can be different people.'],
['encanto','Who wrote the original songs for Disney’s Encanto?',['Lin-Manuel Miranda','Taylor Swift','FINNEAS','John Williams'],'Lin-Manuel Miranda wrote Encanto’s songs. Music is one way a film develops its story.']
];
for(const[source,prompt,options,why]of POP_QUESTIONS)BANK.music.push([prompt,options,0,why,POP_SOURCES[source],null,'pop-music',1,6]);
function practiceNumber(id,year,prompt,n,why,family,unit='',tier=year===6?2:year===7?4:6){secondaryQuestion(id,year,prompt,[n,n+1,n-1,n+3].map(x=>formatNumber(x)+unit),why,family,tier)}
let practiceSerial=0;
while(Object.values(BANK).reduce((n,a)=>n+a.length,0)<10000){
 const serial=practiceSerial++,v=serial%32,k=Math.floor(serial/32),a=12+k,b=3+k%11,c=5+k%13,year=k%3===0?6:k%3===1?7:8;
 if(v===0){const total=4*a;practiceNumber('maths',6,`A school has ${total} students. One quarter join a reading event. How many join?`,a,`Divide ${total} by 4: ${total} ÷ 4 = ${a}.`,'fraction-quarter')}
 if(v===1)practiceNumber('maths',7,`A rectangle has perimeter ${2*(a+b)} cm and length ${a} cm. What is its width in cm?`,b,`Half the perimeter is ${a+b} cm. Subtract the length: ${a+b} − ${a} = ${b}.`,'reverse-perimeter');
 if(v===2)practiceNumber('maths',8,`Solve ${b}(x + ${c}) = ${b*(a+c)}. What is x?`,a,`Divide by ${b}, then subtract ${c}: x = ${a}.`,'bracket-equation');
 if(v===3)practiceNumber('science',6,`An experiment records temperatures of ${a}°C at the start and ${a+b}°C at the end. What is the rise in °C?`,b,`Temperature change = final − initial = ${a+b} − ${a} = ${b}°C.`,'temperature-rise');
 if(v===4)practiceNumber('science',8,`A moving object travels ${a*b} m in ${b} seconds at constant speed. What is its speed in m/s?`,a,`Speed = distance ÷ time = ${a*b} ÷ ${b} = ${a} m/s.`,'speed-calculation');
 if(v===5)practiceNumber('biology',6,`In a habitat sample, researchers count ${a} beetles, ${b} spiders and ${c} snails. How many animals are counted altogether?`,a+b+c,`Add all three groups: ${a} + ${b} + ${c} = ${a+b+c}. The result describes this sample.`,'habitat-count');
 if(v===6)practiceNumber('biology',7,`A seed trial starts with ${a*5} seeds. Exactly 80% germinate. How many seeds germinate?`,a*4,`80% is four fifths. ${a*5} ÷ 5 × 4 = ${a*4}.`,'germination-percentage');
 if(v===7)practiceNumber('chemistry',6,`A mixture contains ${a} g of salt and ${b*10} g of water. No material is lost. What is its total mass in grams?`,a+b*10,`Mass is conserved when the materials are combined: ${a} + ${b*10} = ${a+b*10} g.`,'mixture-mass');
 if(v===8)practiceNumber('chemistry',8,`A solution has ${a} g of solute in a total volume of 500 mL. How many grams of solute would 1 L contain at the same concentration?`,a*2,`One litre is 1,000 mL, twice 500 mL. Double the solute mass: ${a} × 2 = ${a*2} g.`,'concentration-scale');
 if(v===9){const start=1600+k;practiceNumber('history',6,`A fictional town archive records a bridge opening in ${start} and a repair in ${start+b+10}. How many years separate the events?`,b+10,`Subtract the earlier year from the later year: ${start+b+10} − ${start} = ${b+10}. These dates are invented for timeline practice.`,'archive-timeline')}
 if(v===10){const age=500+k*4;practiceNumber('history',7,`In a fictional excavation record, layer A is estimated at ${age+120} years old and layer B at ${age} years old. How many years older is layer A?`,120,`Compare the estimated ages: ${age+120} − ${age} = 120 years. Real archaeological dates also have uncertainty.`,'archaeology-ages')}
 if(v===11)practiceNumber('geography',6,`A simple map uses 1 cm to show 2 km. Two places are ${a} cm apart on the map. How far apart are they in km?`,a*2,`Multiply map distance by the scale: ${a} × 2 = ${a*2} km.`,'map-scale');
 if(v===12)practiceNumber('geography',7,`A rain gauge records ${a} mm on Monday, ${a+b} mm on Tuesday and ${a+2*b} mm on Wednesday. What is the mean daily rainfall in mm?`,a+b,`Add the three values and divide by 3: ${3*a+3*b} ÷ 3 = ${a+b} mm.`,'rainfall-mean');
 if(v===13)practiceNumber('economics',6,`A club earns $${a*10} at a stall and spends $${b*5} on supplies. What is the surplus in dollars?`,a*10-b*5,`Surplus = income − costs = ${a*10} − ${b*5} = $${a*10-b*5}.`,'stall-surplus');
 if(v===14)practiceNumber('economics',8,`A club invests $${a*100} at 3% simple interest per year for 2 years. How much interest is earned in dollars?`,a*6,`Simple interest = principal × rate × time = ${a*100} × 0.03 × 2 = $${a*6}.`,'interest-two-years');
 if(v===15)practiceNumber('civics',6,`In a fictional class vote, ${a} students vote for option A and ${b} for option B. Nobody abstains. How many votes are cast?`,a+b,`Add the two vote counts: ${a} + ${b} = ${a+b}. This is an invented example, not election news.`,'class-vote-count');
 if(v===16)practiceNumber('social',7,`A community survey has ${a*5} respondents. Exactly 60% support more shade trees. How many respondents support the idea?`,a*3,`60% of ${a*5} is ${a*5} × 0.6 = ${a*3}. A survey describes its respondents and may not represent everyone.`,'shade-survey');
 if(v===17)practiceNumber('digital',6,`A program starts counter at ${a}, adds ${b}, then subtracts 2. What is the final counter value?`,a+b-2,`Follow the instructions in order: ${a} + ${b} − 2 = ${a+b-2}.`,'trace-counter');
 if(v===18)practiceNumber('digital',8,`A program sets total = ${a}. It then repeats “total = total + ${b}” exactly ${c} times. What is the final total?`,a+b*c,`The loop adds ${b} a total of ${c} times: ${a} + ${b} × ${c} = ${a+b*c}.`,'trace-loop');
 if(v===19)practiceNumber('design',6,`A prototype uses ${b} equal supports, each ${a} cm long. What is their combined length in cm, before any cutting waste?`,a*b,`Multiply the number of supports by their length: ${b} × ${a} = ${a*b} cm.`,'material-length');
 if(v===20)practiceNumber('design',7,`A drawing uses a scale of 1:5. A model panel is ${a} cm long in the drawing. What length does it represent in cm?`,a*5,`Multiply the drawing length by 5: ${a} × 5 = ${a*5} cm.`,'design-scale');
 if(v===21)practiceNumber('music',6,`A practice exercise has ${a} bars of 4/4. How many crotchet beats are in the exercise?`,a*4,`There are four crotchet beats in each bar of 4/4: ${a} × 4 = ${a*4}.`,'music-beat-count');
 if(v===22)practiceNumber('music',7,`A music track lasts ${a+60} seconds. An introduction lasts ${b} seconds and an ending lasts ${c} seconds. How many seconds remain in the middle?`,a+60-b-c,`Subtract the introduction and ending: ${a+60} − ${b} − ${c} = ${a+60-b-c} seconds.`,'track-structure');
 if(v===23)practiceNumber('arts',6,`An exhibition has ${b} rows of ${a} drawings. How many drawings are displayed?`,a*b,`The rectangular arrangement contains ${b} × ${a} = ${a*b} drawings.`,'exhibition-array');
 if(v===24)practiceNumber('sports',6,`A relay team completes ${b} equal sections, each ${a*10} m long. What total distance in metres does it cover?`,a*b*10,`Add equal sections by multiplying: ${b} × ${a*10} = ${a*b*10} m.`,'relay-distance');
 if(v===25)practiceNumber('sports',7,`In a fictional basketball skills drill, a player makes ${a} two-point shots and ${b} three-point shots. How many points do those shots score?`,a*2+b*3,`Two-point shots score ${a*2}; three-point shots score ${b*3}. Total = ${a*2+b*3}.`,'basketball-points');
 if(v===26)practiceNumber('health',6,`An activity timetable has ${a} minutes of walking, ${b} minutes of stretching and ${c} minutes of rest. How many minutes does the timetable cover?`,a+b+c,`Add the three scheduled periods: ${a} + ${b} + ${c} = ${a+b+c} minutes. This is timetable practice, not an exercise prescription.`,'activity-timetable');
 if(v===27)practiceNumber('general',6,`A library shelf has ${a} books. A volunteer adds ${b} and lends out ${c}. How many remain on the shelf?`,a+b-c,`Start with ${a}, add ${b}, then subtract ${c}: ${a+b-c} remain.`,'library-stock');
 if(v===28)practiceNumber('logic',6,`Continue this number pattern: ${a}, ${a+b}, ${a+2*b}, ${a+3*b}, …`,a+4*b,`Each step adds ${b}. The next number is ${a+3*b} + ${b} = ${a+4*b}.`,'arithmetic-sequence');
 if(v===29)practiceNumber('logic',8,`Two mystery numbers have sum ${a*2+b} and difference ${b}. What is the smaller number?`,a,`Subtract the difference from the sum and halve: (${a*2+b} − ${b}) ÷ 2 = ${a}.`,'two-number-reasoning');
 if(v===30){const people=['Ari','Mia','Noah','Zara','Finn','Ruby','Leo','Isla','Owen','Jade'],name=people[k%10],noun=['shells','tokens','stickers','cards','marbles'][Math.floor(k/10)%5];secondaryQuestion('english',6,`Read: “${name} packed ${a} ${noun} before the trip. Later, ${name} gave ${b} to a friend.” Which event happened first?`,[`${name} packed ${a} ${noun}.`,`${name} gave ${b} ${noun} away.`,`${name} lost every item.`,`${name} returned from the trip.`],`“Before the trip” and “Later” establish the sequence. Packing is the first stated event.`,'reading-sequence',1)}
 if(v===31){const start=10+k%20,step=2+Math.floor(k/20);secondaryQuestion('languages',6,`In an invented classroom number code, “lu” means ${start}, “lulu” means ${start+step}, and “lululu” means ${start+step*2}. If the pattern continues, what does “lulululu” mean?`,[start+step*3,start+step*2,start+step*4,start].map(String),`Each extra “lu” adds ${step}. The next value is ${start+step*2} + ${step} = ${start+step*3}. This is an invented pattern, not a real language.`,'invented-language-pattern',2)}
}
QUESTION_COUNT=Object.values(BANK).reduce((n,a)=>n+a.length,0);
// Diversify each ten-question set by skill family, while preferring unseen, stage-appropriate items.
const stageRankedDeck=buildQuestionDeck;
buildQuestionDeck=function(subject){const items=stageRankedDeck(subject),stage=questionStage(),fresh=items.filter(q=>!profile.questionSeen[questionKey(q)]),old=items.filter(q=>profile.questionSeen[questionKey(q)]),cost=q=>Math.abs(itemDifficulty(q)-stage.tier)+(stage.year-(q.q[8]||6))*3;const output=[],families=new Set();for(const item of fresh){const family=item.id+':'+(item.q[6]||'concept');if(!families.has(family)&&cost(item)<=3){output.push(item);families.add(family)}}const keys=new Set(output.map(questionKey));return [...output,...fresh.filter(q=>!keys.has(questionKey(q))),...old]};
